package com.nightbeam.donutshards;
import com.nightbeam.donutshards.api.*;import com.nightbeam.donutshards.command.CommandRouter;import com.nightbeam.donutshards.database.*;import com.nightbeam.donutshards.reward.RewardService;import com.nightbeam.donutshards.scheduler.*;import com.nightbeam.donutshards.service.MessageService;import com.nightbeam.donutshards.shop.ShopService;import com.nightbeam.donutshards.transaction.*;import com.nightbeam.donutshards.zone.*;import org.bukkit.configuration.file.YamlConfiguration;import org.bukkit.plugin.ServicePriority;import org.bukkit.plugin.java.JavaPlugin;import java.io.File;import java.util.List;import java.util.concurrent.atomic.AtomicBoolean;import java.util.concurrent.atomic.AtomicInteger;import java.util.logging.Level;
public final class DonutShardsPlugin extends JavaPlugin {private final AtomicBoolean stopping=new AtomicBoolean();private SchedulerService scheduler;private volatile DatabaseManager database;private volatile RewardService rewards;private volatile ShopService shop;private volatile ZoneService zones;private final AtomicInteger tax=new AtomicInteger();
 @Override public void onEnable(){scheduler=SchedulerFactory.create(this);getLogger().info("Starting DonutShards "+getDescription().getVersion()+" on "+scheduler.platform()+" with region-safe scheduling.");scheduler.async(this::bootstrap);}
 private void bootstrap(){try{getDataFolder().mkdirs();for(var file:List.of("config.yml","database.yml","messages.yml","rewards.yml","zones.yml","shop.yml","gui.yml","anti-abuse.yml"))if(!new File(getDataFolder(),file).exists())saveResource(file,false);var config=loadConfig();var db=YamlConfiguration.loadConfiguration(new File(getDataFolder(),"database.yml"));var type=DatabaseConfig.Type.valueOf(db.getString("type","SQLITE").toUpperCase());var databaseConfig=new DatabaseConfig(type,db.getString("sqlite-file","donutshards.db"),db.getString("host","127.0.0.1"),db.getInt("port",3306),db.getString("database","donutshards"),db.getString("username","donutshards"),db.getString("password",""),Math.max(1,db.getInt("pool-size",10)),db.getLong("connection-timeout-ms",10000));database=new DatabaseManager(databaseConfig,getDataFolder().toPath());database.migrate();if(stopping.get()){database.close();return;}var repository=new TransactionRepository(database,config.getString("server-id","server-1"),config.getLong("maximum-balance",9_000_000_000_000_000L));var tx=new TransactionService(repository,scheduler);var messages=new MessageService();zones=new ZoneService(this,new File(getDataFolder(),"zones.yml"));tax.set(Math.max(0,Math.min(10000,config.getInt("transfer.tax-basis-points",0))));var api=new DefaultDonutShardsApi(tx,zones,tax.get());shop=new ShopService(this,tx,scheduler,messages);rewards=new RewardService(tx,scheduler,messages);var commands=new CommandRouter(tx,scheduler,messages,zones,shop,tax,this::reloadConfigs);scheduler.global(()->{if(stopping.get())return;for(var name:List.of("shards","shardshop","afk","shardmanager")){var command=getCommand(name);if(command!=null){command.setExecutor(commands);command.setTabCompleter(commands);}}getServer().getPluginManager().registerEvents(shop,this);getServer().getPluginManager().registerEvents(rewards,this);getServer().getPluginManager().registerEvents(new ZoneListener(zones),this);getServer().getServicesManager().register(DonutShardsApi.class,api,this,ServicePriority.Normal);rewards.start();getLogger().info("Database connected and DonutShards is ready.");});}catch(Throwable error){getLogger().log(Level.SEVERE,"DonutShards could not initialize; commands remain unavailable.",error);}}
 public void reloadConfigs(){var config=loadConfig();tax.set(Math.max(0,Math.min(10000,config.getInt("transfer.tax-basis-points",0))));if(zones!=null)zones.reload();getLogger().info("DonutShards configuration reloaded.");}
 private YamlConfiguration loadConfig(){return YamlConfiguration.loadConfiguration(new File(getDataFolder(),"config.yml"));}
 @Override public void onDisable(){stopping.set(true);if(rewards!=null)rewards.stop();if(shop!=null)shop.clear();if(zones!=null)zones.clear();if(scheduler!=null)scheduler.cancelAll();var db=database;if(db!=null)db.close();getServer().getServicesManager().unregisterAll(this);getLogger().info("DonutShards shut down cleanly.");}}
